import * as React from 'react'
import { cn } from '@/lib/utils'
import { useMergedRefs } from '@/lib/merge-refs'
import { ProgressBar } from '@/components/ui/progress-bar'
import type { TabBarItem } from '@/components/ui/tab-bar'

export interface SidebarTabsProps {
  items: TabBarItem[]
  activeId: string | null
  onSelect: (id: string) => void
  'aria-label': string
  className?: string
}

/**
 * Vertical counterpart to the DS TabBar -- the wide-desktop (xl+) presentation
 * of the same tab set, rendered into a Layout's left sidebar. The horizontal
 * TabBar covers the narrower phases; this is shown only once the sidebar
 * appears (the page hides one or the other via CSS, never both at once). Takes
 * the same TabBarItem[] so it is a drop-in: the active item gets the nav-style
 * highlight, its optional icon sits before the label, and its progress shows as
 * a thin bar pinned to the bottom edge -- the same indicator as the mobile
 * underline, kept off the label so the accent never hurts text contrast (see
 * ProgressFill).
 */
export const SidebarTabs = React.forwardRef<HTMLDivElement, SidebarTabsProps>(function SidebarTabs(
  { items, activeId, onSelect, 'aria-label': ariaLabel, className },
  ref,
) {
  const listRef = React.useRef<HTMLDivElement>(null)
  const mergedRef = useMergedRefs(listRef, ref)

  // Vertical roving-tabindex keyboard model (the horizontal TabBar's Left/Right,
  // turned 90 degrees): Up/Down move between tabs, Home/End jump to the ends.
  const handleKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
    if (!items.length) return
    const current = activeId ? items.findIndex((t) => t.id === activeId) : -1
    let next: number | null = null
    if (e.key === 'ArrowDown') next = current < items.length - 1 ? current + 1 : 0
    else if (e.key === 'ArrowUp') next = current > 0 ? current - 1 : items.length - 1
    else if (e.key === 'Home') next = 0
    else if (e.key === 'End') next = items.length - 1
    if (next !== null) {
      e.preventDefault()
      const item = items[next]
      onSelect(item.id)
      listRef.current?.querySelector<HTMLElement>(`[data-tab-id="${item.id}"]`)?.focus()
    }
  }

  return (
    <div
      ref={mergedRef}
      role="tablist"
      aria-orientation="vertical"
      aria-label={ariaLabel}
      onKeyDown={handleKeyDown}
      className={cn('flex flex-col gap-1', className)}
    >
      {items.map((item) => {
        const isActive = item.id === activeId
        return (
          <button
            key={item.id}
            role="tab"
            aria-selected={isActive}
            tabIndex={isActive ? 0 : -1}
            data-tab-id={item.id}
            onClick={() => onSelect(item.id)}
            className={cn(
              // Regular rounded highlight, like the header nav items. The
              // progress fill sits as a layer between the highlight and the text;
              // overflow-hidden clips it to the rounded corners (the focus ring
              // is an outline, so it is not clipped).
              'wj-focus-ring relative flex w-full items-center gap-2 overflow-hidden rounded-lg px-3 py-2 text-left text-sm font-medium transition-colors',
              isActive
                ? 'bg-[var(--color-warm-100)] text-[var(--color-warm-700)] dark:bg-[var(--color-neutral-800)] dark:text-white'
                : 'text-[var(--color-text-secondary-light)] hover:bg-[var(--color-warm-50)] dark:text-[var(--color-text-secondary-dark)] dark:hover:bg-[var(--color-neutral-800)]'
            )}
          >
            {isActive && (
              <ProgressFill progress={item.progress} count={item.count} underline={item.underline} />
            )}
            {item.icon && (
              <span aria-hidden className="relative flex shrink-0 items-center">
                {item.icon}
              </span>
            )}
            <span className="relative block leading-snug">{item.label}</span>
          </button>
        )
      })}
    </div>
  )
})

SidebarTabs.displayName = 'SidebarTabs'

/**
 * The active item's indicator -- a thin bar pinned to the bottom of the item,
 * mirroring the mobile/tablet TabBar underline, over the item's highlight
 * background. Kept at the bottom (rather than filling the item) so the accent
 * never sits behind the label, which fails contrast in light mode. The button's
 * rounded corners clip the bar's bottom ends -- fine for the continuous bars,
 * but the segment strip is inset to the label's padding instead: the corner
 * curve would swallow the first (whole) dot, and discrete dots read as broken
 * when clipped.
 * - underline 'shimmer' (special / occasional tabs): a dimmed accent line with a
 *   slow full-accent sweep (static under reduced motion);
 * - 'indeterminate' (free / count streaks): the DS segment-accumulation
 *   indicator -- solid dots on a faint dotted track, every 10 collapsing into a
 *   pill -- driven by the item's `count` (plain dotted line without one);
 * - a 0..1 number: a full-accent fill spanning that fraction over a faint-accent
 *   (low opacity) track, matching the mobile/tablet TabBar underline;
 * - no progress concept (plain sections): nothing -- the highlight alone marks
 *   the active item.
 */
function ProgressFill({
  progress,
  count,
  underline,
}: {
  progress?: number | 'indeterminate'
  count?: number
  underline?: 'wave' | 'shimmer'
}) {
  if (underline === 'shimmer') {
    return (
      <span aria-hidden className="absolute inset-x-0 bottom-0 h-[3px]">
        <span className="absolute inset-0 bg-[var(--color-accent-500)] motion-safe:opacity-50" />
        <span className="wj-tab-shimmer absolute inset-0" />
      </span>
    )
  }
  if (progress == null) return null
  if (progress === 'indeterminate') {
    return (
      // inset-x-2 equals the button's rounded-lg corner radius (8px), so the
      // strip spans the full straight run of the bottom edge -- the first dot
      // starts exactly where the corner curve ends, without hugging the label
      // padding (12px read as too much clearance).
      <span aria-hidden className="absolute inset-x-2 bottom-0 h-[3px]">
        <ProgressBar indeterminate count={count} size="xs" decorative className="h-full" />
      </span>
    )
  }
  const pct = Math.round(Math.max(0, Math.min(1, progress)) * 100)
  return (
    <span aria-hidden className="absolute inset-x-0 bottom-0 h-[3px]">
      {/* Faint-accent track for the unfilled part + full-accent fill on top --
          the same treatment as the DS ProgressBar / mobile TabBar underline (the
          button's rounded corners clip the bar's ends). */}
      <span
        className="absolute inset-0"
        style={{ background: 'color-mix(in srgb, var(--color-accent-500) 35%, transparent)' }}
      />
      <span
        className="absolute inset-y-0 start-0 bg-[var(--color-accent-500)] motion-safe:transition-[width] duration-500 ease-out"
        style={{ width: `${pct}%` }}
      />
    </span>
  )
}
